/* Private experiment, appended to the reviewed c/interface.c at build time.
 * Not a guest API. The host adapter supplies only immutable allowlisted assets.
 * No raw bytecode, module, flags, path or filename API is exposed to a script.
 */
#define QTS_TRUSTED_MAX_BYTES (16 * 1024 * 1024)

/* Consume only the exception generated by the immediately preceding operation.
 * Never stringify it (which could call guest code). No exception escapes this
 * status-only bridge and there is no cross-boundary JSValue ownership transfer.
 */
static void qts_trusted_drop_exception(JSContext *ctx) {
  JS_FreeValue(ctx, JS_GetException(ctx));
}

/* Owned temporary input/output storage, charged by the runtime allocator. */
uint8_t *QTS_TrustedBytecodeAlloc(JSContext *ctx, size_t length) {
  if (length == 0 || length > QTS_TRUSTED_MAX_BYTES) return NULL;
  uint8_t *buffer = js_malloc(ctx, length);
  if (!buffer) qts_trusted_drop_exception(ctx);
  return buffer;
}

void QTS_TrustedBytecodeFree(JSContext *ctx, uint8_t *buffer) {
  js_free(ctx, buffer);
}

/* Borrow val; caller retains/frees the compile-only handle. On success the
 * writer buffer is owned by the caller and must use the matching js_free.
 * No REFERENCE, SAB or byte-swapping modes, and no modules.
 */
uint8_t *QTS_TrustedBytecodeWrite(JSContext *ctx, JSValueConst *val, size_t *length) {
  *length = 0;
  if (JS_VALUE_GET_TAG(*val) != JS_TAG_FUNCTION_BYTECODE) return NULL;
  uint8_t *buffer = JS_WriteObject(ctx, length, *val, JS_WRITE_OBJ_BYTECODE);
  if (!buffer) qts_trusted_drop_exception(ctx);
  return buffer;
}

/* Borrow input. JS_ReadObject without ROM_DATA owns its copied representation,
 * so the caller can free input immediately after this synchronous operation.
 * Returns 0 on success, -1 read/OOM, -2 non-global input, -3 evaluation failure.
 * After JS_EvalFunction consumes code, NEVER JS_FreeValue(code) again.
 */
int QTS_TrustedBytecodeReadEval(JSContext *ctx, const uint8_t *buffer, size_t length) {
  JSValue code = JS_ReadObject(ctx, buffer, length, JS_READ_OBJ_BYTECODE);
  if (JS_IsException(code)) {
    qts_trusted_drop_exception(ctx);
    return -1;
  }
  if (JS_VALUE_GET_TAG(code) != JS_TAG_FUNCTION_BYTECODE) {
    JS_FreeValue(ctx, code);
    return -2;
  }
  JSValue result = JS_EvalFunction(ctx, code);
  if (JS_IsException(result)) {
    qts_trusted_drop_exception(ctx);
    return -3;
  }
  JS_FreeValue(ctx, result);
  return 0;
}

/* Host-only diagnostic: unlike the existing high-level memory report this
 * includes temporary js_malloc buffers, not just reachable guest objects.
 */
double QTS_TrustedMallocSize(JSRuntime *rt) {
  JSMemoryUsage usage;
  JS_ComputeMemoryUsage(rt, &usage);
  return usage.malloc_size;
}
